import argparse,hashlib,importlib.util,pathlib
p=argparse.ArgumentParser();p.add_argument('--exe',required=True);p.add_argument('--checker',required=True);p.add_argument('--checker-sha256',required=True);p.add_argument('--mangled');a=p.parse_args();checker=pathlib.Path(a.checker).resolve();assert hashlib.sha256(checker.read_bytes()).hexdigest()==a.checker_sha256;exe=pathlib.Path(a.exe).resolve();assert exe.name=='Replay';spec=importlib.util.spec_from_file_location('wifi_ui_original_check',checker);module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module);module.BUILD=exe.parent;module.replay(a.mangled)
